local SeedDrillMaker = {}
local PRODUCTS = {
    simple_wood_seed_drill = { name = "Preprosta lesena sejalnica", woodCost = 4, ironCost = 1, time = 5, cost = 120, food = 20, happiness = 1, description = "Preprosta lesena sejalnica za setev." },
    iron_tube_seed_drill = { name = "Železnocévna sejalnica", woodCost = 4, ironCost = 2, time = 7, cost = 300, food = 32, happiness = 2, prestige = 2, description = "Železnocévna sejalnica za trgovce." },
    silver_geared_seed_drill = { name = "Srebrnozobčana sejalnica", woodCost = 4, silverCost = 1, ironCost = 2, time = 11, cost = 720, food = 48, happiness = 2, prestige = 6, description = "Srebrnozobčana sejalnica za plemiče." },
    gold_trimmed_seed_drill = { name = "Zlatookrasna sejalnica", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 2, time = 15, cost = 1700, food = 62, happiness = 3, prestige = 14, description = "Zlatookrasna sejalnica za visoke plemiče." },
    jewel_set_seed_drill = { name = "Draguljasta sejalnica", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 2, jewelCost = 1, time = 19, cost = 3700, food = 78, happiness = 5, prestige = 27, description = "Sejalnica z draguljem za visoko plemstvo." },
    royal_grand_seed_drill = { name = "Kraljevski veliki sejalnica", woodCost = 6, goldCost = 2, silverCost = 2, ironCost = 2, jewelCost = 2, pearlCost = 2, time = 26, cost = 8000, food = 95, happiness = 12, prestige = 58, description = "Velika kraljevska sejalnica z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    seed_drill_workshop = { name = "Sejalniška delavnica", cost = { gold = 280, wood = 160, stone = 120, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    agricultural_loft = { name = "Kmetijska podstrešje", cost = { gold = 1000, wood = 320, stone = 240, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_seed_drill_atelier = { name = "Mojstrski sejalniški atelje", cost = { gold = 2800, wood = 380, stone = 480, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_agriculture_palace = { name = "Kraljevska kmetijska palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
SeedDrillMaker.woodStock = 22; SeedDrillMaker.ironStock = 12; SeedDrillMaker.silverStock = 6; SeedDrillMaker.goldStock = 6; SeedDrillMaker.jewelStock = 4; SeedDrillMaker.pearlStock = 4
SeedDrillMaker.productStock = {}; SeedDrillMaker.buildings = {}; SeedDrillMaker.maker = nil; SeedDrillMaker.activeMaking = {}; SeedDrillMaker.totalProducts = 0; SeedDrillMaker.dayTimer = 0
function SeedDrillMaker.init() SeedDrillMaker.woodStock=22; SeedDrillMaker.ironStock=12; SeedDrillMaker.silverStock=6; SeedDrillMaker.goldStock=6; SeedDrillMaker.jewelStock=4; SeedDrillMaker.pearlStock=4; SeedDrillMaker.productStock={}; SeedDrillMaker.buildings={}; SeedDrillMaker.maker=nil; SeedDrillMaker.activeMaking={}; SeedDrillMaker.totalProducts=0; SeedDrillMaker.dayTimer=0; print("[SeedDrillMaker] Royal Seed Drill Maker System initialized (6 products, 4 buildings)") end
function SeedDrillMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SeedDrillMaker.maker={name=n or ("Sejalničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sejalničar najet: %s (spretnost: %d)",SeedDrillMaker.maker.name,s),"success") end; return true end
function SeedDrillMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SeedDrillMaker.build(id) local ok,e=SeedDrillMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SeedDrillMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SeedDrillMaker.getQualityBonus() local b=0; for _,bd in ipairs(SeedDrillMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SeedDrillMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and SeedDrillMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and SeedDrillMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and SeedDrillMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SeedDrillMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SeedDrillMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SeedDrillMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SeedDrillMaker.buildings==0 then return false,"Potrebna sejalniška delavnica" end; if not SeedDrillMaker.maker then return false,"Potreben sejalničar" end; return true end
function SeedDrillMaker.make(pt,qty) qty=qty or 1; local ok,e=SeedDrillMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then SeedDrillMaker.woodStock=SeedDrillMaker.woodStock-d.woodCost*qty end; if d.ironCost then SeedDrillMaker.ironStock=SeedDrillMaker.ironStock-d.ironCost*qty end; if d.silverCost then SeedDrillMaker.silverStock=SeedDrillMaker.silverStock-d.silverCost*qty end; if d.goldCost then SeedDrillMaker.goldStock=SeedDrillMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SeedDrillMaker.jewelStock=SeedDrillMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SeedDrillMaker.pearlStock=SeedDrillMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SeedDrillMaker.maker then t=math.max(1,t-math.floor(SeedDrillMaker.maker.skill/13)) end; table.insert(SeedDrillMaker.activeMaking,{id="seeddrill_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SeedDrillMaker.completeMaking(m) local q=1.0+(SeedDrillMaker.getQualityBonus()/100); if SeedDrillMaker.maker then q=q+(SeedDrillMaker.maker.skill/140) end; q=math.min(2.5,q); SeedDrillMaker.productStock[m.productType]=(SeedDrillMaker.productStock[m.productType] or 0)+m.quantity; SeedDrillMaker.totalProducts=SeedDrillMaker.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SeedDrillMaker.maker then SeedDrillMaker.maker.itemsMade=SeedDrillMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SeedDrillMaker.maker.skill=math.min(100,SeedDrillMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sejalnica izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"seeddrill.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function SeedDrillMaker.update(dt) if not _G.state then return end; SeedDrillMaker.dayTimer=SeedDrillMaker.dayTimer+dt; if SeedDrillMaker.dayTimer>=30 then SeedDrillMaker.dayTimer=0; for i=#SeedDrillMaker.activeMaking,1,-1 do local m=SeedDrillMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SeedDrillMaker.completeMaking(m); table.remove(SeedDrillMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SeedDrillMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SeedDrillMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SeedDrillMaker.getStats() return {woodStock=SeedDrillMaker.woodStock,ironStock=SeedDrillMaker.ironStock,silverStock=SeedDrillMaker.silverStock,goldStock=SeedDrillMaker.goldStock,jewelStock=SeedDrillMaker.jewelStock,pearlStock=SeedDrillMaker.pearlStock,productStock=SeedDrillMaker.productStock,numBuildings=#SeedDrillMaker.buildings,hasMaker=SeedDrillMaker.maker~=nil,makerName=SeedDrillMaker.maker and SeedDrillMaker.maker.name or "—",makerSkill=SeedDrillMaker.maker and SeedDrillMaker.maker.skill or 0,activeMaking=#SeedDrillMaker.activeMaking,totalProducts=SeedDrillMaker.totalProducts} end
return SeedDrillMaker
